<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-13 {"mainTitle":"向いていない人・向いている人","subTitle":"FOR WHOM","headingLevel":2,"colorMain":"#16305c"} -->
<div class="wp-block-wdl-lw-pr-custom-title-13 lw-pr-custom-title-13" style="--color-main:#16305c"><h2 class="ttl"><span class="sub">FOR WHOM</span><span class="main">向いていない人・向いている人</span><div class="left"></div><div class="right"></div></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-13 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center" style="margin-top:28px;margin-bottom:24px">先に「向いていない人」から書きます。当てはまる人は、たぶん戻したくなります。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-column-1 {"columnsPc":2,"columnWidthsPc":[1,1],"columnsSp":1,"rowGapPc":20,"columnGapPc":20,"rowGapSp":16,"itemBgNone":false,"itemBgTypePc":"solid","itemBgColorPc":"#eef2f7","itemBgTypeSp":"solid","itemBgColorSp":"#eef2f7","itemPaddingTopPc":26,"itemPaddingBottomPc":26,"itemPaddingLeftPc":26,"itemPaddingRightPc":26,"itemPaddingTopSp":20,"itemPaddingBottomSp":20,"itemPaddingLeftSp":18,"itemPaddingRightSp":18,"itemBorderRadiusTopLeftPc":8,"itemBorderRadiusTopRightPc":8,"itemBorderRadiusBottomRightPc":8,"itemBorderRadiusBottomLeftPc":8,"itemBorderRadiusTopLeftSp":8,"itemBorderRadiusTopRightSp":8,"itemBorderRadiusBottomRightSp":8,"itemBorderRadiusBottomLeftSp":8} -->
<div class="wp-block-wdl-lw-pr-column-1 lw-pr-column-1" style="--column-1-wrap-padding-pc:0px 0px 0px 0px;--column-1-wrap-padding-sp:0px 0px 0px 0px;--column-1-border-color-pc:rgb(131, 131, 131);--column-1-border-width-pc:0px;--column-1-border-style-pc:solid;--column-1-border-color-sp:rgb(131, 131, 131);--column-1-border-width-sp:0px;--column-1-border-style-sp:solid;--column-1-bdr-pc:0px 0px 0px 0px;--column-1-bdr-sp:0px 0px 0px 0px;--column-1-gtc-pc:1fr 1fr;--column-1-gtc-sp:1fr;--column-1-row-gap-pc:20px;--column-1-row-gap-sp:16px;--column-1-column-gap-pc:20px;--column-1-column-gap-sp:20px;--column-1-item-bg-pc:#eef2f7;--column-1-item-bg-sp:#eef2f7;--column-1-item-min-h-pc:0px;--column-1-item-min-h-sp:0px;--column-1-item-padding-pc:26px 26px 26px 26px;--column-1-item-padding-sp:20px 18px 20px 18px;--column-1-item-bdr-pc:8px 8px 8px 8px;--column-1-item-bdr-sp:8px 8px 8px 8px;--column-1-item-border-color-pc:rgb(131, 131, 131);--column-1-item-border-width-pc:0px;--column-1-item-border-style-pc:solid;--column-1-item-border-color-sp:rgb(131, 131, 131);--column-1-item-border-width-sp:0px;--column-1-item-border-style-sp:solid"><div class="custom_wrap"><!-- wp:heading {"level":3,"style":{"color":{"text":"#c1440e"},"typography":{"fontSize":"18px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}}} -->
<h3 class="has-text-color" style="color:#c1440e;font-size:18px;line-height:1.5;margin-top:0px;margin-bottom:12px">向いていない人</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"15px","lineHeight":"2"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:15px;line-height:2;margin-top:0px;margin-bottom:0px">・昼休みに動画を見る習慣がある<br>・困ったときに電話で聞きたい<br>・支払いを口座振替にしたい<br>・通話アプリを入れるのが面倒</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":3,"style":{"color":{"text":"#1668b0"},"typography":{"fontSize":"18px","lineHeight":"1.5"},"spacing":{"margin":{"top":"0px","bottom":"12px"}}}} -->
<h3 class="has-text-color" style="color:#1668b0;font-size:18px;line-height:1.5;margin-top:0px;margin-bottom:12px">向いている人</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2733"},"typography":{"fontSize":"15px","lineHeight":"2"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2733;font-size:15px;line-height:2;margin-top:0px;margin-bottom:0px">・家と職場にWi-Fiがある<br>・問い合わせがチャットでも気にならない<br>・クレジットカードで払っている<br>・合わなければ翌月に戻せばいい、と思える</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-column-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/lw-pr-custom-title-13 {"mainTitle":"いっしょに買った端末","subTitle":"DEVICE","headingLevel":2,"colorMain":"#16305c"} -->
<div class="wp-block-wdl-lw-pr-custom-title-13 lw-pr-custom-title-13" style="--color-main:#16305c"><h2 class="ttl"><span class="sub">DEVICE</span><span class="main">いっしょに買った端末</span><div class="left"></div><div class="right"></div></h2></div>
<!-- /wp:wdl/lw-pr-custom-title-13 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center" style="margin-top:28px;margin-bottom:24px">4年使った端末が電池切れになったので、乗り換えと同時に買い替えました。<span class="lw-br on_500px"></span>会社から買わず、自分で選んで持ち込んでいます。</p>
<!-- /wp:paragraph -->
